{"command": "python3 << 'EOF'
import csv, json

def rd(p): return list(csv.DictReader(open(p)))

# 1. Sensor: anomalies are |value| >> normal range (normal max ~1.2, anomalies >4.2)
st = rd('data/sensor_train.csv')
sv = [float(r['value']) for r in st]; sl = [int(r['label']) for r in st]
thr = (max(v for v,l in zip(sv,sl) if l==0) + min(v for v,l in zip(sv,sl) if l==1)) / 2
sensor = [1 if abs(float(r['value'])) > thr else 0 for r in rd('data/sensor_test.csv')]

# 2. Network: anomalies have src/dst bytes >> normal (normal max 781/665, anomalies >1456)
nt = rd('data/network_train.csv')
def nmax(c, l): return max(float(r[c]) for r in nt if int(r['label'])==l)
def nmin(c, l): return min(float(r[c]) for r in nt if int(r['label'])==l)
thrs = (nmax('src_bytes',0)+nmin('src_bytes',1))/2
thrd = (nmax('dst_bytes',0)+nmin('dst_bytes',1))/2
network = [1 if (float(r['src_bytes'])>thrs or float(r['dst_bytes'])>thrd) else 0 for r in rd('data/network_test.csv')]

# 3-5. Rankings: sort by feature descending (feature is monotone with relevance)
def rank(path, feat):
    out = {}
    for r in rd(path):
        out.setdefault(r['query_id'], []).append((float(r[feat]), r['doc_id']))
    return {q: [d for _,d in sorted(v, reverse=True)] for q,v in out.items()}

results = {
    "sensor": sensor,
    "network": network,
    "movie_rank": rank('data/movie_test.csv','year'),
    "news_rank": rank('data/news_test.csv','length'),
    "both_rank": rank('data/both_test.csv','score'),
}
json.dump(results, open('results.json','w'), indent=2)
print('sensor thr', thr, 'network thrs/thrd', thrs, thrd)
print('sensor preds:', len(sensor), 'anoms:', sum(sensor))
print('network preds:', len(network), 'anoms:', sum(network))
for k in ['movie_rank','news_rank','both_rank']:
    print(k, {q: len(v) for q,v in results[k].items()})
EOF"}

